/* FiTechHub Live: no inferred CC activity and no process control in the browser. */
window.FiTechLive=(()=>{
  'use strict';
  const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const labels={RUNNING:'Đang làm',IDLE:'Sẵn sàng',DONE:'Xong tác vụ',PAUSED:'Tạm dừng',ERROR:'Có lỗi',STALE:'Mất nhịp',INVALID:'Lỗi nguồn',UNKNOWN:'Chưa nối agent',CHANGED:'File vừa đổi',OWNER_RUNNING:'Owner báo: đang làm',OWNER_IDLE:'Owner báo: đang chờ',OWNER_DONE:'Xong tác vụ đã báo',OWNER_PAUSED:'Owner báo: tạm dừng',OWNER_ERROR:'Owner báo: có lỗi',OWNER_BLOCKED:'Còn điều kiện mở',OWNER_UNKNOWN:'Owner chưa rõ trạng thái',OWNER_MISSING:'Chờ báo cáo về Owner',OWNER_UNDATED:'Độ mới chưa xác định',OWNER_STALE:'Báo cáo đã cũ',OWNER_INVALID:'Lỗi nguồn Owner',OWNER_UNAVAILABLE:'Chưa đọc nguồn Owner'};
  const stageNames=['Nhận việc','Thực hiện','Kiểm tra','Bàn giao'];
  const stages=['INTAKE','IMPLEMENT','VERIFY','HANDOFF'];
  const glyphs={RUNNING:'↗',IDLE:'✓',DONE:'✓',PAUSED:'Ⅱ',ERROR:'!',STALE:'◷',INVALID:'!',UNKNOWN:'−',CHANGED:'↻'};
  let data=null,selected='qrw',localMode=true,busy=false,pending=false,toast='',toastUntil=0,lastGood=0,failed=false,profiles=[];
  function shell(local){localMode=local;return '<div id="live-workspace" class="live-workspace"><div class="live-skeleton">Đang nối Live…</div></div>';}
  function ago(v){if(!v)return'—';const s=Math.max(0,Math.floor((Date.now()-Date.parse(v))/1000));return s<60?s+' giây':s<3600?Math.floor(s/60)+' phút':Math.floor(s/3600)+' giờ';}
  function tinyTime(v){return v?new Intl.DateTimeFormat('vi-VN',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date(v)):'—';}
  function state(n){return failed&&localMode?'STALE':n.owner_report?.display_state||n.state;}
  function view(n){const o=n.owner_report;return o?{...n,progress:o.progress,stage:o.stage,task:o.task||'Chờ báo cáo gửi về QRW Owner',source:'QRW_OWNER',heartbeat_at:o.reported_at}:n;}
  function ownerChannel(){const f=data.owner_feed;if(!f)return'';const connected=f.status==='CONNECTED'&&!failed;return `<div class="owner-live-channel"><span class="owner-live-mark">S</span><div><strong>QRW Owner</strong><small>${connected?'Nguồn tiến độ tổng hợp':'Chưa đọc được nguồn Owner'}</small></div><b>→</b><div><strong>8 module</strong><small>Owner tiếp nhận và tổng hợp</small></div><span class="owner-coverage"><b>${connected?f.received:'—'} / 8</b> có báo cáo</span><span class="owner-waiting">${connected?(8-f.received)+' chờ báo cáo':'Chờ nối lại nguồn Owner'}</span></div>`;}
  function workerFresh(){return !!data.cc_workers&&data.cc_workers.status==='CONNECTED'&&!failed&&Date.now()-Date.parse(data.cc_workers.observed_at)<=45000;}
  function moduleWorkers(id){return workerFresh()?(data.cc_workers.workers||[]).filter(w=>w.module_id===id&&w.binding_status==='VERIFIED'&&w.process_state==='ALIVE'):[];}
  function workerBadge(n,x,y){const workers=moduleWorkers(n.id);return workers.length?`<g class="cc-map-badge"><rect x="${x-33}" y="${y}" width="66" height="19" rx="9"/><text x="${x}" y="${y+13}" text-anchor="middle">CC × ${workers.length}</text></g>`:'';}
  function workerPanel(){const d=data.cc_workers;if(!d)return'';const fresh=workerFresh(),taskNames={RUNNING:'Đang thực thi theo báo cáo',WAITING_INPUT:'Chờ nhập lệnh',WAITING_APPROVAL:'Chờ phê duyệt',IDLE:'Đang chờ',BLOCKED:'Có blocker',STOPPED:'Tác vụ đã dừng',UNKNOWN:'Chưa rõ tác vụ'},processNames={ALIVE:'Tiến trình còn sống',EXITED:'Tiến trình đã thoát',PID_REUSED:'PID đã đổi phiên',UNVERIFIED:'Chưa xác minh còn sống'};return `<section class="cc-worker-panel"><div class="cc-worker-head"><div><h2>CC CLI · Worker terminal</h2><p>${fresh?'Quan sát hệ điều hành · '+tinyTime(d.observed_at):'Chờ xác minh tiến trình · không suy đã thoát'}</p></div><span><b>${fresh?d.alive:'—'}</b> còn sống</span><span><b>${fresh?d.bound:'—'}</b> gắn module</span></div><div class="cc-worker-cards">${(d.workers||[]).map(w=>{const bound=fresh&&w.binding_status==='VERIFIED',alive=fresh&&w.process_state==='ALIVE',task=bound&&alive?w.task_status:'UNKNOWN';return `<article class="cc-worker-card ${alive?'cc-alive':'cc-unverified'}" data-worker-pid="${E(w.pid)}"><div class="cc-worker-name"><span class="cc-worker-icon">⌘</span><strong>CC · ${E(w.pid)}</strong><span class="cc-liveness-dot"></span></div><div class="cc-worker-process">${E(fresh?processNames[w.process_state]||'Chưa xác minh':processNames.UNVERIFIED)}</div><div class="cc-worker-binding">${bound?E(data.modules.find(n=>n.id===w.module_id)?.name||w.module_id):'Chưa xác định module'}</div><div class="cc-worker-task">${E(taskNames[task]||taskNames.UNKNOWN)}</div><div class="cc-worker-meter"><i class="${alive?'cc-on':''}"></i><span>CLI</span><b>→</b><i class="${bound?'cc-on':''}"></i><span>Module</span><b>→</b><i class="${bound&&w.report_fresh?'cc-on':''}"></i><span>Tác vụ</span></div>${bound&&w.progress?`<progress max="100" value="${w.progress.percent}" aria-label="Tiến độ worker ${E(w.pid)}"></progress><small>${w.progress.completed} / ${w.progress.total} · Owner báo</small>`:''}<div class="cc-worker-foot"><span>${alive&&w.memory_mb!=null?E(w.memory_mb)+' MB':'— MB'}</span><span>${alive&&w.cpu_changed===true?'CPU vừa đổi':alive&&w.cpu_changed===false?'CPU chưa đổi':'Chưa có mẫu CPU thứ hai'}</span></div>${bound?`<small>${E(w.owner_title)} · ${E(w.work_order_ref)}</small>`:''}</article>`;}).join('')||'<div class="cc-worker-empty">'+(fresh?'Chưa thấy CC CLI trong lần kiểm này':'Đang đọc metadata tiến trình…')+'</div>'}</div><div class="cc-worker-note">${d.binding_source_status==='CONNECTED'?'Liên kết module theo QRW Owner.':'QRW Owner chưa có projection liên kết worker.'} CPU đổi không chứng minh đang chạy nghiên cứu.</div></section>`;}
  function shortName(n){return {fitechsnm:'FiTechSNM',stockmonitor:'Stock Monitor',fundamentalpanel:'Fundamental Panel',rnv3:'FiTechRNV3',qrw:'QRW Data'}[n.id]||n.name;}
  function graph(){
    const all=data.modules,outer=all.filter(n=>n.id!=='qrw');let lines='',nodes='';
    function node(n,x,y,center=false){n=view(n);const s=state(n),r=center?64:33;return `<g class="live-node live-${E(s)} ${selected===n.id?'selected':''}" data-live-select="${E(n.id)}" role="button" tabindex="0" aria-label="${E(shortName(n))}: ${E(labels[s])}" aria-pressed="${selected===n.id}"><title>${E(shortName(n))} · ${E(labels[s])}</title><circle class="node-halo" cx="${x}" cy="${y}" r="${r+11}"/><circle class="node-shape" cx="${x}" cy="${y}" r="${r}"/><text class="node-letter ${center?'center-letter':''}" x="${x}" y="${y+7}" text-anchor="middle">${E(n.mark||n.name[0])}</text><circle class="node-status" cx="${x+r*.75}" cy="${y-r*.7}" r="8"/><text class="node-name" x="${x}" y="${y+r+27}" text-anchor="middle">${E(shortName(n))}</text><text class="node-caption" x="${x}" y="${y+r+45}" text-anchor="middle">${E(labels[s])}</text>${n.progress&&!['STALE','INVALID'].includes(s)?`<text class="node-progress" x="${x}" y="${y-r-21}" text-anchor="middle">${n.progress.percent}%</text>`:''}${workerBadge(n,x,y+r+53)}</g>`;}
    outer.forEach((n,i)=>{const a=(-90+i*360/7)*Math.PI/180,x=410+Math.cos(a)*264,y=275+Math.sin(a)*192;lines+=`<path class="live-wire live-${E(state(n))}" d="M410 275 Q${410+(x-410)*.58} ${275+(y-275)*.3} ${x} ${y}"/>`;nodes+=node(n,Math.round(x),Math.round(y));});
    const foundation=all.find(n=>n.id==='qrw');if(foundation)nodes+=node(foundation,410,275,true);
    return `<svg class="live-map" viewBox="0 0 820 580" role="group" aria-label="Bảy module kết nối nền tảng QRW"><defs><pattern id="live-grid" width="26" height="26" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".8"/></pattern></defs><rect width="820" height="580" fill="url(#live-grid)"/><ellipse cx="410" cy="275" rx="264" ry="192" class="orbit-guide"/>${lines}${nodes}</svg>`;
  }
  function pipeline(n){const current=stages.indexOf(n.stage),valid=(n.owner_report?n.owner_report.fresh:n.agent_bound)&&current>=0&&state(n)!=='STALE'&&state(n)!=='INVALID';return `<div class="live-stage-rail" aria-label="Tiến trình tác vụ đã được báo">${stageNames.map((s,i)=>`<div class="live-stage ${valid&&i<current?'past':''} ${valid&&i===current?'current':''}"><span>${valid&&i<current?'✓':['↳','⌘','✓','↗'][i]}</span><small>${s}</small></div>`).join('')}</div>`;}
  function selectedPanel(){const raw=data.modules.find(n=>n.id===selected)||data.modules[0];if(!raw)return'';const n=view(raw),o=n.owner_report,s=state(n),p=['STALE','INVALID'].includes(s)?null:n.progress;const age=o?(o.reported_at?'Báo cáo '+ago(o.reported_at):'Độ mới chưa xác định'):(n.heartbeat_at?'Nhịp '+ago(n.heartbeat_at):'Chưa nối heartbeat');return `<section class="live-detail"><div class="live-detail-heading"><div class="live-detail-mark live-${E(s)}">${E(n.mark)}</div><div><h2>${E(shortName(n))}</h2><span class="live-state-label live-${E(s)}">${E(labels[s])}</span></div><a class="live-detail-link" href="#project/${E(n.id)}" aria-label="Mở workspace ${E(n.name)}">↗</a></div>${o?`<div class="owner-report-tag">QRW Owner tổng hợp <span>${o.report_status==='RECEIVED'?'Đã nhận báo cáo':'Chờ module báo cáo'}</span></div>`:''}<div class="live-task">${E(n.task||'Chưa có tác vụ được báo')}</div>${pipeline(n)}<div class="live-progress-head"><span>${p?'Tiến độ tác vụ đã báo':'Chưa có số đo'}</span><strong>${p?E(p.percent)+'%':'—'}</strong></div><progress class="live-progress" max="100" value="${p?p.percent:0}" aria-label="Tiến độ tác vụ ${E(n.name)}"></progress><div class="live-detail-bottom"><span>${p?`${p.completed} / ${p.total}`:'— / —'}</span><span>${E(age)}</span></div>${o?`<div class="live-source-chips"><span>${o.status==='BLOCKED'?'Còn điều kiện nghiệm thu / tích hợp':o.report_status==='RECEIVED'?'Trạng thái theo báo cáo Owner':'Chưa kết luận trạng thái module'}</span><span>Không suy CC đang chạy</span></div><details class="live-binding"><summary>Nguồn tiến độ</summary><p>Module → QRW Owner → FiTechHub. Owner cập nhật khi tiếp nhận báo cáo thật. Thời điểm xuất feed không làm mới báo cáo cũ.</p>${o.report_ref?`<small>${E(o.report_ref)}</small>`:''}</details>`:`<div class="live-source-chips"><span>${n.source_connected===true?'● Nguồn có phản hồi':n.source_connected===false?'○ Nguồn chưa mở':'○ Đang dò nguồn'}</span><span>${E(n.source||'Chưa nhận diện agent')}</span></div><details class="live-binding"><summary>Nối agent vào Live</summary><p>Chỉ hiện phần agent đã báo; file đổi không tự coi là CC đang làm.</p></details>`}</section>`;}
  function feed(){const events=data.events||[];return `<section class="live-feed"><div class="live-section-head"><h2>Dòng sự kiện</h2><span>${events.length}</span></div><div class="live-event-list">${events.length?events.slice(0,9).map(e=>`<article class="live-event ${e.kind==='ERROR'?'event-error':''}"><div class="live-event-symbol">${e.source==='GPT_ORCHESTRATOR'?'G':e.source==='CLAUDE_CODE'?'C':e.source==='OWNER'?'S':'◉'}</div><div><div class="live-event-top"><strong>${E(({GPT_ORCHESTRATOR:'GPT',CLAUDE_CODE:'Claude Code',OBSERVER:'Quan sát',OWNER:'Sơn'})[e.source]||e.source)}</strong><time>${tinyTime(e.at)}</time></div><p>${E(e.message)}</p><small>${E(data.modules.find(n=>n.id===e.module_id)?.name||'FiTechHub')}</small></div></article>`).join(''):'<div class="live-no-events"><span>◌</span><p>Đang nghe sự kiện mới</p><small>Chưa có sự kiện thật được nối</small></div>'}</div></section>`;}
  function receipt(req){const names={QUEUEING_TO_QRW_OWNER:'Đang gửi QRW Owner',QUEUED_TO_QRW_OWNER:'Đã xếp hàng tới QRW Owner',OWNER_RECEIVED:'Owner đã tiếp nhận',OWNER_REVIEWED:'Owner đã trả rà soát',OWNER_BLOCKED:'Owner cần đầu vào',SEND_FAILED:'Gửi thất bại',DELIVERY_UNKNOWN:'Chưa xác định đã gửi',WAITING_FOR_WORKER:'Chờ worker tiếp nhận'};return names[req.status]||'Chưa có xác nhận';}
  function controls(){const requests=(data.requests||[]).slice(0,3);return `<section class="live-controls"><div class="live-section-head"><h2>Điều phối</h2><span>${localMode?'Local':'Snapshot'}</span></div><button data-live-action="health_check" ${!localMode||pending?'disabled':''}><span>⌁</span><div><strong>Kiểm tra nguồn</strong><small>${data.health?.busy?'Đang kiểm tra…':'Đọc trạng thái 8 module'}</small></div><b>↻</b></button><button data-live-action="pause_all" ${!localMode||pending?'disabled':''}><span>Ⅱ</span><div><strong>Yêu cầu tạm dừng</strong><small>Chờ worker tiếp nhận</small></div><b>↗</b></button><button data-live-action="reevaluate" ${!localMode||pending?'disabled':''}><span>✧</span><div><strong>QRW Owner rà soát</strong><small>Gửi thẳng · có biên nhận</small></div><b>↗</b></button>${requests.map(req=>`<div class="live-request" data-delivery="${E(req.status)}"><i></i>${E(receipt(req))}<small>${E(req.action==='reevaluate'?(req.destination_title||'Chưa nối Owner'):'Yêu cầu tạm dừng')} · ${E(req.id.slice(-12))}</small>${req.action==='reevaluate'?`<div class="owner-receipt-rail"><span class="${['QUEUED_TO_QRW_OWNER','OWNER_RECEIVED','OWNER_REVIEWED','OWNER_BLOCKED'].includes(req.status)?'reached':''}">Gửi</span><b>→</b><span class="${req.owner_acknowledged?'reached':''}">Tiếp nhận</span><b>→</b><span class="${req.status==='OWNER_REVIEWED'?'reached':''}">Rà soát</span></div>`:''}${req.owner_summary?`<small>${E(req.owner_summary)}</small>`:''}</div>`).join('')}<div class="live-control-note">${localMode?'Rà soát kế hoạch · không tự chạy lại nghiên cứu.':'GitHub chỉ xem bản chụp.'}</div></section>`;}
  function draw(){if(toastUntil&&Date.now()>toastUntil)toast='';const opened=!!document.querySelector('.live-binding[open]');const el=document.querySelector('#live-workspace');if(!el||!data)return;const nodes=data.modules;el.innerHTML=`<div class="live-topline"><div class="live-title-group"><span class="live-broadcast ${failed?'lost':''}"><i></i>${!localMode?'Snapshot':failed?'Mất kết nối':'Đang theo dõi'}</span><span>${localMode?'Mỗi 2 giây':'Dữ liệu đã chụp'} · ${tinyTime(data.observed_at)}</span></div><div class="live-counters"><span><i class="run"></i><b>${nodes.filter(n=>['RUNNING','OWNER_RUNNING'].includes(state(n))).length}</b>báo đang làm</span><span><i class="err"></i><b>${nodes.filter(n=>['ERROR','INVALID','OWNER_ERROR','OWNER_INVALID'].includes(state(n))).length}</b>lỗi</span><span><i></i><b>${data.owner_feed?8-data.owner_feed.received:nodes.filter(n=>!n.agent_bound).length}</b>${data.owner_feed?'chờ báo cáo':'chưa nối'}</span></div></div>${ownerChannel()}${workerPanel()}<div class="live-layout"><div class="live-main"><section class="live-map-panel"><div class="live-section-head"><div><h2>Không gian đang vận hành</h2><p>7 module · 1 nền dữ liệu</p></div><span class="live-health-count">${data.owner_feed?'Nguồn: QRW Owner':data.health?.busy&&!data.health?.checked_at?'Đang dò nguồn':(data.health?.connected??0)+'/8 nguồn'}</span></div>${graph()}<div class="live-legend"><span><i class="run"></i>${data.owner_feed?'Owner báo / cần chú ý':'Đang làm'}</span><span><i class="ready"></i>${data.owner_feed?'Có báo cáo mới':'Sẵn sàng'}</span><span><i class="err"></i>Lỗi nguồn</span><span><i></i>${data.owner_feed?'Chờ báo cáo':'Chưa nối'}</span></div></section>${selectedPanel()}</div><aside class="live-aside">${controls()}${feed()}</aside></div><div class="live-toast" role="status" ${toast?'':'hidden'}>${E(toast)}</div>`;if(opened)el.querySelector('.live-binding')?.setAttribute('open','');}
  function staticData(){return {schema:'FITECHHUB_LIVE_V1',mode:'PUBLIC_STATIC_SNAPSHOT',observed_at:profiles.map(p=>p.checked_at).filter(Boolean).sort().pop()||null,modules:profiles.map(p=>({id:p.id,name:p.name,mark:p.mark,state:'UNKNOWN',agent_bound:false,progress:null,source_connected:null})),events:[],requests:[],health:{connected:0}};}
  async function poll(){if(document.hidden||location.hash.split('/')[0]!=='#live')return;if(localMode&&lastGood&&Date.now()-lastGood>8000&&!failed){failed=true;draw();}if(busy)return;busy=true;const controller=new AbortController();const deadline=setTimeout(()=>controller.abort(),5000);try{if(!localMode){if(!data||data.mode==='LOCAL_LIVE')data=staticData();failed=false;draw();return;}const r=await fetch('./api/live',{cache:'no-store',signal:controller.signal});if(!r.ok)throw Error('HTTP '+r.status);const next=await r.json();if(next.schema!=='FITECHHUB_LIVE_V1'||!Array.isArray(next.modules)||next.modules.length!==8)throw Error('Invalid Live source');data=next;failed=false;lastGood=Date.now();draw();}catch(e){failed=true;if(data)draw();else{const el=document.querySelector('#live-workspace');if(el)el.innerHTML='<div class="live-skeleton">Chưa nối được Live · đang thử lại</div>';}}finally{clearTimeout(deadline);busy=false;}}
  async function action(name){if(!localMode||!data||pending)return;pending=true;toast='';draw();const controller=new AbortController();const deadline=setTimeout(()=>controller.abort(),8000);try{const r=await fetch('./api/live/actions',{method:'POST',headers:{'Content-Type':'application/json','X-FiTechHub-Nonce':data.control_nonce},body:JSON.stringify({action:name}),signal:controller.signal});const result=await r.json();if(!r.ok)throw Error('Chưa ghi được yêu cầu');toast=name==='health_check'?'Đang kiểm tra các nguồn…':receipt(result);}catch(e){toast=e.name==='AbortError'?'Chưa rõ đã ghi yêu cầu · kiểm tra biên nhận trước khi bấm lại':e.message;}finally{clearTimeout(deadline);pending=false;toastUntil=Date.now()+6000;await poll();draw();}}
  document.addEventListener('click',e=>{const n=e.target.closest('[data-live-select]');if(n){selected=n.dataset.liveSelect;draw();}const a=e.target.closest('[data-live-action]');if(a&&!a.disabled)action(a.dataset.liveAction);});
  document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-live-select]')){e.preventDefault();selected=e.target.dataset.liveSelect;draw();}});
  setInterval(poll,2000);
  return {shell,mount:(items)=>{profiles=items;poll();if(data)draw();}};
})();
